<?php // Marquee slider of gallery photos marked "Na úvode" (homepage and About page). Expects $sliderItems. ?>
<div class="home-gallery-slider" aria-label="Galéria MotoCare Pro" style="--slides: <?= count($sliderItems) ?>"><div class="home-gallery-track"><?php for ($copy = 0; $copy < 2; $copy++): ?><div class="home-gallery-group" <?= $copy === 1 ? 'aria-hidden="true"' : '' ?>><?php foreach ($sliderItems as $item): $bikeName = (string) ($item['bike'] ?? ''); ?><a class="home-gallery-slide" href="galeria<?= $bikeName !== '' ? '?motorka=' . e(slugify($bikeName)) : '' ?>" <?= $copy === 1 ? 'tabindex="-1"' : '' ?>><img loading="lazy" decoding="async" src="<?= e($item['thumb'] ?? $item['src']) ?>" alt="<?= $copy === 1 ? '' : e(($bikeName !== '' ? $bikeName : 'Motocykel') . ' — fotografia z galérie MotoCare Pro') ?>"><?php if ($bikeName !== ''): ?><span><?= e($bikeName) ?></span><?php endif; ?></a><?php endforeach; ?></div><?php endfor; ?></div></div>
